class $$ProfilesTableTableManager extends RootTableManager<
    _$AppDatabase,
    $ProfilesTable,
    Profile,
    $$ProfilesTableFilterComposer,
    $$ProfilesTableOrderingComposer,
    $$ProfilesTableAnnotationComposer,
    $$ProfilesTableCreateCompanionBuilder,
    $$ProfilesTableUpdateCompanionBuilder,
    (Profile, $$ProfilesTableReferences),
    Profile,
    PrefetchHooks Function(
        {bool accountsRefs,
        bool transactionsRefs,
        bool categoriesRefs,
        bool groceryListsRefs,
        bool unitsRefs,
        bool calculatorEntriesRefs,
        bool voiceCorrectionsRefs,
        bool recurringRuleRefs,
        bool budgetsRefs,
        bool goalsRefs,
        bool forecastStateRefs,
        bool liquidityStateRefs,
        bool cashFlowStateRefs,
        bool recommendationsRefs,
        bool insightsRefs,
        bool financialClosingRefs,
        bool predictionStateRefs,
        bool trendStateRefs,
        bool behaviorStateRefs,
        bool seasonalityStateRefs,
        bool riskStateRefs,
        bool optimizationStateRefs,
        bool simulationStateRefs,
        bool predictionHistoryRefs,
        bool smsTrackedAccountsRefs,
        bool smsImportFingerprintsRefs,
        bool smsImportHistoryRefs})> {
  $$ProfilesTableTableManager(_$AppDatabase db, $ProfilesTable table)
      : super(TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$ProfilesTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$ProfilesTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$ProfilesTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback: ({
            Value<int> id = const Value.absent(),
            Value<String> name = const Value.absent(),
            Value<ProfileType> type = const Value.absent(),
            Value<DateTime> createdAt = const Value.absent(),
          }) =>
              ProfilesCompanion(
            id: id,
            name: name,
            type: type,
            createdAt: createdAt,
          ),
          createCompanionCallback: ({
            Value<int> id = const Value.absent(),
            required String name,
            required ProfileType type,
            Value<DateTime> createdAt = const Value.absent(),
          }) =>
              ProfilesCompanion.insert(
            id: id,
            name: name,
            type: type,
            createdAt: createdAt,
          ),
          withReferenceMapper: (p0) => p0
              .map((e) =>
                  (e.readTable(table), $$ProfilesTableReferences(db, table, e)))
              .toList(),
          prefetchHooksCallback: (
              {accountsRefs = false,
              transactionsRefs = false,
              categoriesRefs = false,
              groceryListsRefs = false,
              unitsRefs = false,
              calculatorEntriesRefs = false,
              voiceCorrectionsRefs = false,
              recurringRuleRefs = false,
              budgetsRefs = false,
              goalsRefs = false,
              forecastStateRefs = false,
              liquidityStateRefs = false,
              cashFlowStateRefs = false,
              recommendationsRefs = false,
              insightsRefs = false,
              financialClosingRefs = false,
              predictionStateRefs = false,
              trendStateRefs = false,
              behaviorStateRefs = false,
              seasonalityStateRefs = false,
              riskStateRefs = false,
              optimizationStateRefs = false,
              simulationStateRefs = false,
              predictionHistoryRefs = false,
              smsTrackedAccountsRefs = false,
              smsImportFingerprintsRefs = false,
              smsImportHistoryRefs = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [
                if (accountsRefs) db.accounts,
                if (transactionsRefs) db.transactions,
