                    currentTable: table,
                    currentColumn: table.profileId,
                    referencedTable:
                        $$AccountsTableReferences._profileIdTable(db),
                    referencedColumn:
                        $$AccountsTableReferences._profileIdTable(db).id,
                  ) as T;
