                        currentTable: table,
                        referencedTable:
                            $$AccountsTableReferences._goalsRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$AccountsTableReferences(db, table, p0).goalsRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.linkedAccountId == item.id),
                        typedResults: items),
                  if (goalHistoryRefs)
                    await $_getPrefetchedData<Account, $AccountsTable,
                            GoalHistoryData>(
                        currentTable: table,
                        referencedTable:
                            $$AccountsTableReferences._goalHistoryRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$AccountsTableReferences(db, table, p0)
                                .goalHistoryRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.accountId == item.id),
                        typedResults: items),
                  if (smsTrackedAccountsRefs)
                    await $_getPrefetchedData<Account, $AccountsTable,
                            SmsTrackedAccount>(
                        currentTable: table,
                        referencedTable: $$AccountsTableReferences
                            ._smsTrackedAccountsRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$AccountsTableReferences(db, table, p0)
                                .smsTrackedAccountsRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.linkedAccountId == item.id),
                        typedResults: items)
